 Here's an example C++ program that generates the Fibonacci sequence using a recursive function. It includes error handling for invalid inputs:

```cpp
#include <iostream>
#include <string>
#include <stdexcept>

using namespace std;

void fibonacci(int n, int a = 0, int b = 1) {
    if (n <= 0) {
        throw invalid_argument("Number of sequence elements must be positive.");
    }

    if (n == 1) {
        cout << a << endl;
        return;
    }

    fibonacci(n - 1, b, a + b);
    cout << b << (n > 2 ? ", " : "");
}

int main() {
    int num1, num2, numElements;

    cout << "Enter the first number in the sequence: ";
    cin >> num1;

    if (!isdigit(num1 + '\x00')) {
        cerr << "Error: First number must be an integer." << endl;
        return 1;
    }

    cout << "Enter the second number in the sequence: ";
    cin >> num2;

    if (!isdigit(num2 + '\x00')) {
        cerr << "Error: Second number must be an integer." << endl;
        return 1;
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> numElements;

    if (numElements <= 0) {
        cerr << "Error: Number of sequence elements must be positive." << endl;
        return 1;
    }

    try {
        fibonacci(numElements, num1, num2);
    } catch (invalid_argument& e) {
        cerr << e.what() << endl;
        return 1;
    }

    return 0;
}
```

