function determineProtocol(inputData) {
  if (inputData.protocol) { // Check if protocol is already provided in inputData
    return inputData.protocol;
  }

  let protocol = null;

  if (inputData.sourceIP && inputData.destinationIP) { // Check for IP addresses
    if (inputData.sourceIP.match(/^[0-9a-f:]{15}([0-9a-f]{1,4})$/) && // IPv6 validation
        inputData.destinationIP.match(/^[0-9a-f:]{15}([0-9a-f]{1,4})$/) && // IPv6 validation
        inputData.port === 80) { // Port check for HTTP
      protocol = 'HTTP';
    }
  } else if (inputData.port && inputData.payload) { // Check for port and payload
    if (inputData.port === 80) { // Port check for HTTP
      protocol = 'HTTP';
    } else if (inputData.port >= 1194) { // Port range for OpenVPN, used by IPv6 over UDP
      protocol = 'UDP';
    }
  }

  return protocol || 'IPv6'; // Default to IPv6 if no other protocol could be determined
}
