 ```javascript title="index.js"
const { NestFactory } = require('@nestjs/core');
const typeorm = require('typeorm');
const AppModule = require('./app.module');

async function bootstrap() {
  await typeorm.createConnection();

  const app = await NestFactory.create(AppModule);

  // Define your roles and permissions here
  const roles = ['admin', 'editor', 'viewer'];
  const permissions = ['create', 'read', 'update', 'delete'];

  // Create an interceptor for handling role-based authorization
  app.useGlobalInterceptors(new AuthInterceptor(roles, permissions));

  await app.listen(3000);
}

bootstrap().catch((err) => console.log(err));

class AuthInterceptor {
  constructor(roles, permissions) {
    this.roles = roles;
    this.permissions = permissions;
  }

  intercept(context, next) {
    const req = context.switchToHttp().getRequest();
    const userRole = req.user.role; // Assuming `req.user` has the user's role

    if (!this.roles.includes(userRole)) {
      throw new UnauthorizedException('Unauthorized');
    }

    const { route, method } = context.switchToHttp().getRequest();
    const routeParts = route.split('/').slice(1);
    const action = routeParts[routeParts.length - 1];

    const allowedActions = req.user.permissions || [];
    const isAllowedAction = this.permissions.some(
      (permission) => allowedActions.includes(permission) && permission === action,
    );

    if (!isAllowedAction) {
      throw new ForbiddenException('Forbidden');
    }

    return next.handle();
  }
}
```

This code sets up a Nest.js application using TypeORM, creates the roles and permissions arrays, defines an interceptor for handling role-based authorization, and throws exceptions when unauthorized or forbidden actions are attempted based on the provided user roles and permissions.

 I'd be happy to help you write an Apps Script function that searches for a place name in a Google Sheets column and stores its latitude and longitude in two other columns. Here's an example of how you might implement this using the Google Maps Places library:

```javascript
function searchPlaceAndWriteCoordinates(sheetName) {
  // Replace "Sheet1" with the name of your sheet.
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
  const apiKey = 'YOUR_API_KEY'; // Replace with your Google Maps API key.

  function searchPlace(address) {
    const request = Maps.newGeocoder().geocode({ address });
    return new Promise((resolve, reject) => {
      if (request.status === 'OK') {
        const location = request.results[0].geometry.location;
        resolve([location.lat(), location.lng()]);
      } else {
        reject('Error geocoding address.');
      }
    });
  }

  const placeColumnIndex = 1; // Replace with the index of the column containing place names.
  const latColumnIndex = 2; // Replace with the index of the column where you want to store the latitudes.
  const lngColumnIndex = 3; // Replace with the index of the column where you want to store the longitudes.

  const dataRange = sheet.getDataRange();
  const values = dataRange.getValues();

  for (let i = 0; i < values.length; i++) {
    const placeName = values[i][placeColumnIndex - 1];
    if (!placeName) continue;

    try {
      const coords = searchPlace(placeName);
      const lat = coords[0];
      const lng = coords[1];
      sheet.getRange(i + 1, latColumnIndex).setValue(lat);
      sheet.getRange(i + 1, lngColumnIndex).setValue(lng);
    } catch (error) {
      Logger.log(`Error searching for place "${placeName}": ${error}`);
    }
  }
}

 Hello! I'm glad you asked for a PHP programming task. Here's a custom function named `smart_sort_array` that meets your requirements:

```php
function smart_sort_array(&$set, $order = 'asc') {
    $n = count($set);
    for ($i = 0; $i < $n - 1; $i++) {
        for ($j = 0; $j < $n - $i - 1; $j++) {
            if (($order == 'desc' && $set[$j]['age'] < $set[$j+1]['age']) || ($order == 'asc' && $set[$j]['age'] > $set[$j+1]['age'])) {
                // Swap elements
                $temp = $set[$j];
                $set[$j] = $set[$j+1];
                $set[$j+1] = $temp;
            }
        }
    }
}
```

This function accepts two arguments: the reference to an array `$set`, and an optional argument `$order` with a default value of 'asc' for ascending order. This function uses the simple switching algorithm for sorting the sub-arrays in the main array based on their 'age' key.

To use this function, simply pass your array as the first argument:

```php
$mySet = array(
