    array('name' => 'Alice', 'address' => 'Los Angeles', 'age' => 32),
    array('name' => 'Bob', 'address' => 'Chicago', 'age' => 22)
);

smart_sort_array($mySet, 'desc'); // Sort in descending order
print_r($mySet);

smart_sort_array($mySet); // Sort in ascending order (default)
print_r($mySet);
```

