            string line3 = treeLines["Tree"][rnd.Next(treeLines["Tree"].Count)];

            Console.WriteLine($"{line1}\n{line2}\n{line3}");

            string haiku = $"<p>{line1}</p>\n<p>{line2}</p>\n<p>{line3}</p>";
            Console.WriteLine("Haiku generated. Displaying on HTML page:");
            Console.Write(haiku);
        }
    }
}
```

