 To identify if a given sentence in Go contains a double negative, follow these steps:

1. Create a slice of specific negative words:
```go
negativeWords := []string{"isn't", "am not", "doesn't", "doesn't have", "doesn't want", "don't", "haven't", "hasn't", "hadn't", "won't", "aren't", "isn't allowed to", "isn't supposed to", "can't", "couldn't", "didn't", "doesn't need to", "needn't", "shouldn't", "wouldn't"}
```

2. Define a function `containsDoubleNegative` that checks if a given sentence contains a double negative:
```go
func containsDoubleNegative(sentence string) bool {
    words := strings.FieldsFunc(sentence, func(r rune) bool { return r == ' ' }) // Split sentence into words using space as delimiter
    for i := range words {
        currentWord := words[i]
        nextWord := ""
        if i < len(words)-1 {
            nextWord = words[i+1]
        }

        // Check for single negation
        if strings.Contains(negativeWords, currentWord) {
            // Check for double negation
            if nextWord != "" && (strings.HasPrefix(nextWord, "not") || strings.Contains(negativeWords, nextWord)) {
                return true
            }
            continue
        }
    }
    return false
}
```

